import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';
import { color, uv, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const disposables = [];

  // Load GLB mesh
  const glb = ctx.glbLoader.load(config.meshUrl);

  // Primary gear (normalized to 1.6-unit diameter)
  const primaryGear = glb.scene.clone();
  primaryGear.scale.set(1.6, 1.6, 1.6);
  primaryGear.position.set(0, 0, 0);
  group.add(primaryGear);

  // Secondary gear (0.9-unit diameter, tooth-meshed at 16:9 ratio)
  const secondaryGear = glb.scene.clone();
  secondaryGear.scale.set(0.9, 0.9, 0.9);
  secondaryGear.position.set(1.15, 0.35, -0.1);
  group.add(secondaryGear);

  // Jewel pivot (0.12-unit sphere at primary hub)
  const jewelGeometry = new THREE.SphereGeometry(0.12, 32, 32);
  const jewelMaterial = new THREE.MeshPhysicalMaterial({
    color: 0xff2a38,
    transmission: 0.6,
    ior: 1.76,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
  });
  const jewel = new THREE.Mesh(jewelGeometry, jewelMaterial);
  group.add(jewel);
  disposables.push(jewelGeometry, jewelMaterial);

  // Arbor shafts (0.05-radius cylinders through both hubs, z-length 0.8)
  const shaftGeometry = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMaterial = new THREE.MeshStandardMaterial({
    color: 0x16161d,
    roughness: 0.5,
  });

  const primaryShaft = new THREE.Mesh(shaftGeometry, shaftMaterial);
  group.add(primaryShaft);

  const secondaryShaft = new THREE.Mesh(shaftGeometry, shaftMaterial.clone());
  secondaryShaft.position.set(1.15, 0.35, -0.1);
  group.add(secondaryShaft);

  disposables.push(shaftGeometry, shaftMaterial, secondaryShaft.material);

  // Contact shadow (ellipse 2.6 x 1.2 units at y=-1.2)
  const shadowGeometry = new THREE.PlaneGeometry(2.6, 1.2);
  const shadowMaterial = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
  });
  const shadow = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadow.position.y = -1.2;
  shadow.position.z = -0.01;
  group.add(shadow);

  disposables.push(shadowGeometry, shadowMaterial);

  // Backdrop plane (7 x 6 at z=-3) with TSL gradient
  const backdropGeometry = new THREE.PlaneGeometry(7, 6);
  const backdropMaterial = new THREE.NodeMaterial();

  // TSL gradient: interpolates from #0b0b10 → #101017 → #16161d using uv.y
  const gradientNode = mix(
    color(0x0b0b10),
    color(0x16161d),
    uv().y
  );
  backdropMaterial.colorNode = gradientNode;

  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -3;
  group.add(backdrop);

  disposables.push(backdropGeometry, backdropMaterial);

  // Render text via fontAtlas (MSDF)
  // Headline: "The going train" at y=-1.7
  const headlineText = ctx.fontAtlas.create({
    text: config.textContent?.headline || 'The going train',
    fontSize: 0.68,
    color: 0xe8ecf2,
    align: 'center',
  });
  headlineText.position.set(0, -1.7, 0);
  group.add(headlineText);

  // Caption: "34 COMPONENTS / HAND-FINISHED" at y=-2.1
  const captionText = ctx.fontAtlas.create({
    text: config.textContent?.caption || '34 COMPONENTS / HAND-FINISHED',
    fontSize: 0.18,
    color: 0xe8ecf2,
    align: 'center',
  });
  captionText.position.set(0, -2.1, 0);
  group.add(captionText);

  // Gear rotation animation (phase-locked, teeth never intersect)
  // Primary: 0.08 rad/s, Secondary: -0.142 rad/s (16:9 ratio)
  const rotationState = { primary: 0, secondary: 0 };
  const rotationTimeline = gsap.timeline({ repeat: -1 });

  rotationTimeline.to(
    rotationState,
    {
      primary: Math.PI * 2,
      secondary: Math.PI * 2 * (0.142 / 0.08),
      duration: (2 * Math.PI) / 0.08,
      ease: 'none',
      onUpdate: () => {
        primaryGear.rotation.z = rotationState.primary;
        secondaryGear.rotation.z = -rotationState.secondary;
      },
    },
    0
  );

  timelines.push(rotationTimeline);

  // Apply orbit cinematic primitive (camera drifts on radius 0.2 at 0.08 rad/s)
  ctx.primitives.orbit(group, { speed: 0.08, radius: 0.2 });

  // Cleanup resources
  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl && tl.kill) tl.kill();
    });

    disposables.forEach((resource) => {
      if (resource && resource.dispose) resource.dispose();
    });

    // Traverse and dispose cloned GLB resources
    glb.scene.traverse((node) => {
      if (node.geometry) node.geometry.dispose();
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach((mat) => {
            if (mat && mat.dispose) mat.dispose();
          });
        } else if (node.material.dispose) {
          node.material.dispose();
        }
      }
    });
  };

  group.userData.handlers = {};

  return group;
}
